def is_wildcard_match(s: str, p: str) -> bool:
    s_idx = p_idx = 0
    star_idx = -1
    s_temp = -1
    while s_idx < len(s):
        if p_idx < len(p) and p[p_idx] in {s[s_idx], '?'}:
            s_idx += 1
            p_idx += 1
        elif p_idx < len(p) and p[p_idx] == '*':
            star_idx = p_idx
            s_temp = s_idx
            p_idx += 1
        elif star_idx != -1:
            p_idx = star_idx + 1
            s_temp += 1
            s_idx = s_temp
        else:
            return False
    while p_idx < len(p) and p[p_idx] == '*':
        p_idx += 1
    return p_idx == len(p)
